def solve(inputs: dict) -> float:
    A=inputs['A']; B=inputs['B']; C=inputs['C']; D=inputs['D']; MOD=inputs['MOD']; K=int(inputs['K'])
    M=[[A%MOD,B%MOD],[C%MOD,D%MOD]]
    R=[[1,0],[0,1]]
    def mul(X,Y):
        return [[(X[0][0]*Y[0][0]+X[0][1]*Y[1][0])%MOD,(X[0][0]*Y[0][1]+X[0][1]*Y[1][1])%MOD],[(X[1][0]*Y[0][0]+X[1][1]*Y[1][0])%MOD,(X[1][0]*Y[0][1]+X[1][1]*Y[1][1])%MOD]]
    while K:
        if K&1: R=mul(R,M)
        M=mul(M,M)
        K//=2
    return float(sum(sum(row) for row in R))

